import React from 'react';
import { Link } from 'react-router-dom';
import project1 from '../assets/project1.png';
import project2 from '../assets/project2.png';

const projects = [
  {
    id: 1,
    title: 'Project 1',
    description: 'Description of project 1',
    image: project1,
    link: 'https://github.com/yourusername/project1',
    technologies: ['React', 'Node.js', 'MongoDB']
  },
  {
    id: 2,
    title: 'Project 2',
    description: 'Description of project 2',
    image: project2,
    link: 'https://github.com/yourusername/project2',
    technologies: ['React', 'Express', 'MySQL']
  },
];

const Projects = () => {
  return (
    <div className="w-full min-h-screen text-gray-100 flex justify-center items-center py-32 bg-gradient-to-r from-gray-900 to-gray-700">
      <div className="max-w-screen-lg mx-auto px-8 py-12">
        <h2 className="text-5xl font-extrabold mb-12 text-center text-gray-200">
          Projets Réalisés
        </h2>
        <div className="grid gap-8 sm:grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
          {projects.map((project) => (
            <div key={project.id} className="bg-gray-800 bg-opacity-80 p-6 rounded-lg shadow-lg transform hover:-translate-y-2 transition duration-300 ease-in-out">
              <img src={project.image} alt={project.title} className="rounded-md mb-4 w-full h-48 object-cover shadow-lg" />
              <h3 className="text-2xl font-bold mb-2 text-gray-100">{project.title}</h3>
              <p className="text-lg mb-4 text-gray-300">{project.description}</p>
              <ul className="text-gray-400 mb-4">
                {project.technologies.map((tech, index) => (
                  <li key={index} className="inline-block bg-gray-700 px-2 py-1 rounded mr-2 text-sm">{tech}</li>
                ))}
              </ul>
              <Link to={`/project/${project.id}`} className="text-blue-400 hover:underline text-lg">
                Voir le projet
              </Link>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Projects;
