import React from 'react';
import { FaArrowCircleUp } from 'react-icons/fa';

const ScrollButton = () => {
  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth',
    });
  };

  return (
    <div className="fixed bottom-4 right-4 z-50">
      <button
        className="w-12 h-12 rounded-full transition-all shadow-lg hover:shadow-2xl transform hover:scale-110 hover:rotate-12"
        title="Défiler vers le haut"
        onClick={scrollToTop}
      >
        <FaArrowCircleUp fontSize={50} color="#313131" className="bg-white rounded-full" />
      </button>
    </div>
  );
};

export default ScrollButton;
