import React, { useState, useEffect, useRef } from 'react';
import { Chart } from 'react-chartjs-2';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { FaPlay, FaStop, FaRedo } from 'react-icons/fa';

ChartJS.register(ArcElement, Tooltip, Legend);

const texts = {
  en: "The quick brown fox jumps over the lazy dog. This is a common English sentence that is used for typing practice. It contains all the letters of the alphabet, making it an ideal sample text for testing typing speed. To improve your typing skills, practice regularly with this sentence and other similar texts. Remember to maintain proper posture and hand positioning while typing. Over time, you will notice a significant improvement in your typing speed and accuracy. Typing is a valuable skill that is essential in today's digital world. Whether you are writing emails, creating documents, or coding, fast and accurate typing can save you a lot of time. Keep practicing and challenge yourself to type faster and more accurately each day.",
  fr: "Le vif renard brun saute par-dessus le chien paresseux. Cette phrase est couramment utilisée pour les exercices de dactylographie en français. Elle contient toutes les lettres de l'alphabet, ce qui en fait un texte idéal pour tester la vitesse de frappe. Pour améliorer vos compétences en dactylographie, pratiquez régulièrement avec cette phrase et d'autres textes similaires. N'oubliez pas de maintenir une posture correcte et une bonne position des mains pendant que vous tapez. Avec le temps, vous remarquerez une amélioration significative de votre vitesse et de votre précision de frappe. La dactylographie est une compétence précieuse qui est essentielle dans le monde numérique d'aujourd'hui. Que vous écriviez des emails, créiez des documents ou codiez, une frappe rapide et précise peut vous faire gagner beaucoup de temps. Continuez à vous entraîner et défiez-vous de taper plus vite et plus précisément chaque jour.",
  ar: "الثعلب البني السريع يقفز فوق الكلب الكسول. هذه جملة شائعة تستخدم لممارسة الطباعة باللغة العربية. تحتوي على جميع حروف الأبجدية، مما يجعلها نصًا مثاليًا لاختبار سرعة الطباعة. لتحسين مهاراتك في الطباعة، مارس بانتظام باستخدام هذه الجملة ونصوص مشابهة أخرى. تذكر أن تحافظ على وضعية الجسم الصحيحة ووضعية اليدين أثناء الطباعة. مع مرور الوقت، ستلاحظ تحسنًا كبيرًا في سرعة ودقة الطباعة لديك. الطباعة مهارة قيمة وضرورية في العالم الرقمي اليوم. سواء كنت تكتب رسائل بريد إلكتروني أو تنشئ مستندات أو تبرمج، فإن الطباعة السريعة والدقيقة يمكن أن توفر لك الكثير من الوقت. استمر في التدريب وتحدي نفسك للطباعة بشكل أسرع وأكثر دقة كل يوم."
};

const SpeedTypingGame = () => {
  const [language, setLanguage] = useState('en');
  const [text, setText] = useState('');
  const [timeRemaining, setTimeRemaining] = useState(120); // 2 minutes
  const [isRunning, setIsRunning] = useState(false);
  const [wordCount, setWordCount] = useState(0);
  const [typedText, setTypedText] = useState('');
  const [charCount, setCharCount] = useState(0);
  const [correctCharCount, setCorrectCharCount] = useState(0);
  const [currentSegment, setCurrentSegment] = useState(0); // Track the current segment
  const inputRef = useRef(null);

  useEffect(() => {
    setText(texts[language]);
  }, [language]);

  useEffect(() => {
    if (isRunning && timeRemaining > 0) {
      const timer = setTimeout(() => {
        setTimeRemaining(prevTime => prevTime - 1);
      }, 1000);
      return () => clearTimeout(timer);
    } else if (timeRemaining === 0) {
      endGame();
    }
  }, [timeRemaining, isRunning]);

  useEffect(() => {
    if (typedText.split(' ').length % 20 === 0) { // Change the segment every 20 words
      setCurrentSegment(Math.floor(typedText.split(' ').length / 20));
    } else if (typedText.split(' ').length < currentSegment * 20) {
      // Adjust the segment if the user deletes enough text
      setCurrentSegment(Math.floor(typedText.split(' ').length / 20));
    }
  }, [typedText]);

  const startGame = () => {
    setIsRunning(true);
    setTimeRemaining(120); // 2 minutes
    setTypedText('');
    setCharCount(0);
    setCorrectCharCount(0);
    inputRef.current.disabled = false;
    inputRef.current.focus();
  };

  const stopGame = () => {
    setIsRunning(false);
    endGame();
  };

  const restartGame = () => {
    setIsRunning(false);
    setTimeRemaining(120); // Reset the timer to 2 minutes
    setTypedText('');
    setCharCount(0);
    setCorrectCharCount(0);
    setWordCount(0);
    setCurrentSegment(0); // Reset the segment
    setIsRunning(true); // Start the game again
    inputRef.current.disabled = false;
    inputRef.current.focus();
  };

  const endGame = () => {
    setWordCount(calculateWordCount(typedText));
  };

  const handleChange = (e) => {
    const value = e.target.value;
    setTypedText(value);
    setCharCount(value.length);
    setCorrectCharCount(calculateCorrectChars(value));
  };

  const calculateWordCount = (text) => {
    const words = text.trim().split(' ').filter(word => word !== '');
    return words.length;
  };

  const calculateCorrectChars = (typedText) => {
    const originalText = text.substring(0, typedText.length);
    return typedText.split('').filter((char, index) => char === originalText[index]).length;
  };

  const getWordClass = (word, globalIndex) => {
    const typedWords = typedText.split(' ');
    if (globalIndex < typedWords.length) {
      const typedWord = typedWords[globalIndex];
      if (typedWord === word) {
        return 'bg-green-300';
      } else if (typedWord !== word && typedWord.startsWith(word.substring(0, typedWord.length))) {
        return 'bg-gray-300';
      } else {
        return 'bg-red-300';
      }
    }
    return '';
  };

  const getCurrentTextSegment = () => {
    const words = text.split(' ');
    const start = currentSegment * 20;
    const end = start + 20;
    return words.slice(start, end).join(' ');
  };

  const currentWordIndex = typedText.split(' ').length - 1;
  const currentSegmentWords = getCurrentTextSegment().split(' ');

  const data = {
    labels: ['Correct Characters', 'Incorrect Characters'],
    datasets: [
      {
        data: [correctCharCount, charCount - correctCharCount],
        backgroundColor: ['#4caf50', '#f44336'],
        hoverBackgroundColor: ['#66bb6a', '#ef5350'],
      },
    ],
  };

  const options = {
    responsive: true,
  };

  return (
    <div className="max-w-screen-lg w-full mx-auto px-4 sm:px-8 py-8 bg-white bg-opacity-90 rounded-lg shadow-2xl backdrop-blur-md">
      <h2 className="text-3xl sm:text-5xl font-extrabold mb-8 sm:mb-12 text-center text-gray-800">
        Speed Typing Game
      </h2>
      <div className="mb-4 sm:mb-8 flex justify-center space-x-2 sm:space-x-4">
        <button 
          onClick={() => setLanguage('en')} 
          className={`px-2 sm:px-4 py-1 sm:py-2 rounded ${language === 'en' ? 'bg-blue-500 text-white' : 'bg-gray-200 text-gray-800'}`}>
          English
        </button>
        <button 
          onClick={() => setLanguage('fr')} 
          className={`px-2 sm:px-4 py-1 sm:py-2 rounded ${language === 'fr' ? 'bg-blue-500 text-white' : 'bg-gray-200 text-gray-800'}`}>
          Français
        </button>
        <button 
          onClick={() => setLanguage('ar')} 
          className={`px-2 sm:px-4 py-1 sm:py-2 rounded ${language === 'ar' ? 'bg-blue-500 text-white' : 'bg-gray-200 text-gray-800'}`}>
          العربية
        </button>
      </div>
      <div className="mb-4 sm:mb-8 flex justify-center space-x-2 sm:space-x-4">
        <button 
          onClick={startGame} 
          className="px-2 sm:px-4 py-1 sm:py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300">
          <FaPlay />
        </button>
        <button 
          onClick={stopGame} 
          disabled={!isRunning} 
          className="px-2 sm:px-4 py-1 sm:py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300">
          <FaStop />
        </button>
        <button 
          onClick={restartGame} 
          disabled={!isRunning} 
          className="px-2 sm:px-4 py-1 sm:py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300">
          <FaRedo />
        </button>
      </div>
      <h3 className="text-xl sm:text-2xl font-bold mb-4 text-center text-gray-800">
        Time Remaining: {timeRemaining} seconds
      </h3>
      <div className="text-left text-gray-800 mb-4 h-32 overflow-auto bg-gray-100 p-4 rounded text-justify flex flex-wrap">
        {currentSegmentWords.map((word, index) => (
          <span
            key={index}
            className={`inline-block mx-1 p-1 text-lg sm:text-2xl flex-grow ${getWordClass(word, currentSegment * 20 + index)} ${currentSegment * 20 + index === currentWordIndex ? 'border-b-2 border-blue-500' : ''}`}
          >
            {word}
          </span>
        ))}
      </div>
      <textarea
        ref={inputRef}
        disabled={!isRunning}
        value={typedText}
        onChange={handleChange}
        className="w-full p-4 h-40 rounded-lg bg-gray-200 text-gray-800 placeholder-gray-400 text-left"
        placeholder="Start typing..."
      />
      {(!isRunning && timeRemaining < 120) && (
        <div className="text-center text-gray-800 mt-8">
          <h3 className="text-2xl font-bold mb-2">Results</h3>
          <p className="text-lg">Words per minute: {wordCount}</p>
          <p className="text-lg">Total characters typed: {charCount}</p>
          <p className="text-lg">Correct characters typed: {correctCharCount}</p>
          <div className="mt-8 w-64 mx-auto">
            <Chart type="pie" data={data} options={options} />
          </div>
        </div>
      )}
    </div>
  );
};

export default SpeedTypingGame;
