import React, { useState, useEffect } from 'react';
import { FaPlay, FaPause, FaRedo, FaTrophy, FaArrowUp, FaArrowDown, FaArrowLeft, FaArrowRight, FaForward } from 'react-icons/fa';

const SnakeGame = () => {
  const [snake, setSnake] = useState([{ x: 10, y: 10 }]);
  const [direction, setDirection] = useState({ x: 0, y: -1 });
  const [food, setFood] = useState({ x: 0, y: 0 });
  const [gameOver, setGameOver] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [score, setScore] = useState(0);

  const gridSize = 20;

  const handleKeyDown = (e) => {
    if (!isPlaying) return;
    switch (e.key) {
      case 'ArrowUp':
        setDirection({ x: 0, y: -1 });
        break;
      case 'ArrowDown':
        setDirection({ x: 0, y: 1 });
        break;
      case 'ArrowLeft':
        setDirection({ x: -1, y: 0 });
        break;
      case 'ArrowRight':
        setDirection({ x: 1, y: 0 });
        break;
      default:
        break;
    }
  };

  const handleDirectionChange = (newDirection) => {
    if (!isPlaying) return;
    setDirection(newDirection);
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isPlaying]);

  useEffect(() => {
    const moveSnake = () => {
      setSnake((prevSnake) => {
        const newSnake = [...prevSnake];
        const head = { x: newSnake[0].x + direction.x, y: newSnake[0].y + direction.y };

        // Check for wall collision
        if (head.x < 0 || head.x >= gridSize || head.y < 0 || head.y >= gridSize) {
          setGameOver(true);
          setIsPlaying(false);
          return prevSnake;
        }

        // Check for self collision
        for (let segment of newSnake) {
          if (head.x === segment.x && head.y === segment.y) {
            setGameOver(true);
            setIsPlaying(false);
            return prevSnake;
          }
        }

        newSnake.unshift(head);

        if (head.x === food.x && head.y === food.y) {
          setFood(generateFoodPosition());
          setScore((prevScore) => prevScore + 1);
        } else {
          newSnake.pop();
        }

        return newSnake;
      });
    };

    if (isPlaying && !gameOver) {
      const interval = setInterval(moveSnake, 200);
      return () => clearInterval(interval);
    }
  }, [direction, food, isPlaying, gameOver]);

  const generateFoodPosition = () => {
    let newFoodPosition;
    do {
      newFoodPosition = {
        x: Math.floor(Math.random() * gridSize),
        y: Math.floor(Math.random() * gridSize),
      };
    } while (
      newFoodPosition.x === 0 ||
      newFoodPosition.x === gridSize - 1 ||
      newFoodPosition.y === 0 ||
      newFoodPosition.y === gridSize - 1
    );
    return newFoodPosition;
  };

  useEffect(() => {
    setFood(generateFoodPosition());
  }, []);

  const startGame = () => {
    setSnake([{ x: 10, y: 10 }]);
    setDirection({ x: 0, y: -1 });
    setFood(generateFoodPosition());
    setGameOver(false);
    setIsPlaying(true);
    setScore(0);
  };

  const stopGame = () => {
    setIsPlaying(false);
  };

  const resumeGame = () => {
    if (!gameOver) setIsPlaying(true);
  };

  const resetGame = () => {
    startGame();
  };

  return (
    <div className="relative flex flex-col items-center">
      <div className="controls flex space-x-4 mb-4">
        <button onClick={startGame} className="px-4 py-2 bg-green-500 text-white rounded">
          <FaPlay />
        </button>
        <button onClick={stopGame} className="px-4 py-2 bg-red-500 text-white rounded">
          <FaPause />
        </button>
        <button onClick={resumeGame} className="px-4 py-2 bg-yellow-500 text-white rounded">
          <FaForward />
        </button>
        <button onClick={resetGame} className="px-4 py-2 bg-blue-500 text-white rounded">
          <FaRedo />
        </button>
      </div>
      <div className="score flex items-center text-2xl text-white mb-4 bg-gray-800 p-2 rounded shadow-lg">
        <FaTrophy className="text-yellow-400 mr-2" />
        {score}
      </div>
      <div className="game-board mx-auto relative bg-gray-900" style={{ width: gridSize * 16, height: gridSize * 16 }}>
        {snake.map((segment, index) => (
          <div
            key={index}
            className="snake-segment absolute bg-green-500"
            style={{
              left: `${segment.x * 16}px`,
              top: `${segment.y * 16}px`,
              width: '16px',
              height: '16px',
            }}
          ></div>
        ))}
        <div
          className="food absolute bg-red-500"
          style={{
            left: `${food.x * 16}px`,
            top: `${food.y * 16}px`,
            width: '16px',
            height: '16px',
          }}
        ></div>
      </div>
      {gameOver && (
        <div className="mt-4 flex flex-col items-center">
          <div className="text-black text-2xl mb-2">
            <span className="px-4 py-2 bg-red-500 text-white rounded-full shadow-lg">Game Over</span>
          </div>
        </div>
      )}
      <div className="direction-controls mt-4 flex flex-col items-center space-y-2">
        <button
          onClick={() => handleDirectionChange({ x: 0, y: -1 })}
          className="p-2 bg-gray-800 text-white rounded-full shadow-lg"
        >
          <FaArrowUp />
        </button>
        <div className="flex space-x-2">
          <button
            onClick={() => handleDirectionChange({ x: -1, y: 0 })}
            className="p-2 bg-gray-800 text-white rounded-full shadow-lg"
          >
            <FaArrowLeft />
          </button>
          <button
            onClick={() => handleDirectionChange({ x: 1, y: 0 })}
            className="p-2 bg-gray-800 text-white rounded-full shadow-lg"
          >
            <FaArrowRight />
          </button>
        </div>
        <button
          onClick={() => handleDirectionChange({ x: 0, y: 1 })}
          className="p-2 bg-gray-800 text-white rounded-full shadow-lg"
        >
          <FaArrowDown />
        </button>
      </div>
    </div>
  );
};

export default SnakeGame;
