import React, { useState, useEffect, useRef } from 'react';
import { useForm, ValidationError } from '@formspree/react';
import { FaPaperPlane } from 'react-icons/fa';
import { useTranslation } from 'react-i18next';

const ContactForm = () => {
  const { t } = useTranslation();
  const [state, handleSubmit] = useForm("mbjbeljb");
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [buttonLeftPosition, setButtonLeftPosition] = useState('50%');
  const buttonRef = useRef(null);
  const formRef = useRef(null);

  const isFormValid = email !== '' && message !== '';

  useEffect(() => {
    if (isFormValid) {
      setButtonLeftPosition('50%');
    }
  }, [isFormValid]);

  const handleMouseMove = (e) => {
    if (isFormValid) return;

    const button = buttonRef.current;
    const form = formRef.current;
    if (!button || !form) return;

    const buttonRect = button.getBoundingClientRect();
    const formRect = form.getBoundingClientRect();
    const mouseX = e.clientX;

    const buttonX = buttonRect.left + buttonRect.width / 2;
    const distanceX = Math.abs(mouseX - buttonX);

    if (distanceX < 100) { // Distance seuil pour déclencher le déplacement
      const maxLeft = formRect.width - buttonRect.width;
      const newLeft = Math.random() * maxLeft;
      setButtonLeftPosition(`${newLeft}px`);
    }
  };

  return (
    <div
      name="contact"
      className="flex flex-col items-center py-16 text-white"
      onMouseMove={handleMouseMove}
    >
      <div className="max-w-screen-md w-full mx-auto p-8 bg-opacity-20 backdrop-blur-md rounded-lg shadow-2xl">
        <div className="text-center my-8">
          <h2 className="text-4xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-blue-500 pb-4 mb-6">
            {t('contact.title')}
          </h2>
        </div>
        <form ref={formRef} onSubmit={handleSubmit} className="space-y-6 relative">
          <div>
            <label htmlFor="email" className="block mb-2 text-sm font-medium text-gray-300">{t('contact.emailPlaceholder')}</label>
            <input
              type="email"
              name="email"
              id="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              placeholder={t('contact.emailPlaceholder')}
              className="w-full p-4 bg-transparent border-b-2 border-gray-500 focus:border-blue-500 focus:outline-none transition duration-300"
            />
            <ValidationError prefix="Email" field="email" errors={state.errors} />
          </div>
          <div>
            <label htmlFor="message" className="block mb-2 text-sm font-medium text-gray-300">{t('contact.messagePlaceholder')}</label>
            <textarea
              name="message"
              id="message"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              required
              placeholder={t('contact.messagePlaceholder')}
              rows="6"
              className="w-full p-4 bg-transparent border-b-2 border-gray-500 focus:border-blue-500 focus:outline-none transition duration-300"
            ></textarea>
            <ValidationError prefix="Message" field="message" errors={state.errors} />
          </div>
          <div
            className="relative flex justify-center"
            style={{
              height: '60px',
              marginTop: '30px' // Centrer verticalement
            }}
          >
            <button
              ref={buttonRef}
              id="submitButton"
              type="submit"
              disabled={state.submitting || !isFormValid}
              className="w-12 h-12 bg-gradient-to-r from-purple-600 to-blue-500 text-white rounded-full hover:bg-gradient-to-l transition duration-300 focus:outline-none focus:ring-2 focus:ring-purple-600 focus:ring-opacity-50 flex items-center justify-center"
              style={{
                position: 'absolute',
                left: buttonLeftPosition,
                top: '50%',
                transform: 'translate(-50%, -50%)',
                cursor: isFormValid ? 'pointer' : 'not-allowed',
              }}
              onClick={(e) => {
                if (!isFormValid) {
                  e.preventDefault();
                }
              }}
            >
              <FaPaperPlane />
            </button>
          </div>
        </form>
        {state.succeeded && (
          <div className="mt-8 text-center">
            <p className="text-lg text-green-500">{t('contact.successMessage')}</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ContactForm;
