import React from 'react';
import avatar from '../assets/avatar.png';
import Cards from '../components/Cards';
import ImageWithSkeleton from '../components/ImageWithSkeleton';
import { useTranslation } from 'react-i18next';

const Home = () => {
  const { t } = useTranslation();

  return (
    <div className="w-full flex justify-center items-center flex-col p-4 mt-32">
      <div className="w-full max-w-4xl flex flex-col p-4">
        <div className="text-center items-center">
          <ImageWithSkeleton
            src={avatar}
            alt={t('home.avatarAlt')}
            className="rounded-full w-60 mb-4 mx-auto shadow-lg transition-transform transform hover:scale-105"
            width="176px"
            height="176px"
            loadingTime={2500}
          />
          <h5 className="text-2xl text-white font-semibold leading-tight mb-2">
            {t('home.name')}
          </h5>
          <p className="text-gray-300 text-xl font-light">
            {t('home.jobTitle')}
          </p>
        </div>
      </div>
      <Cards />
    </div>
  );
};

export default Home;
