import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { FaHome, FaUser, FaProjectDiagram, FaBlog, FaEnvelope, FaStar, FaTools, FaGlobe, FaGamepad } from 'react-icons/fa';
import { useTranslation } from 'react-i18next';
import logo from '../assets/logombe.png';

const Navbar = () => {
  const [menuOpen, setMenuOpen] = useState(false);
  const { t, i18n } = useTranslation();
  const location = useLocation();

  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
  };

  const changeLanguage = (lng) => {
    i18n.changeLanguage(lng);
  };

  // Close menu when location changes
  useEffect(() => {
    setMenuOpen(false);
  }, [location]);

  // Set default language to FR on mount
  useEffect(() => {
    changeLanguage('fr');
  }, []);

  return (
    <nav className="fixed top-0 left-0 w-full z-50 bg-transparent backdrop-blur-md shadow-md">
      <div className="container mx-auto px-6 py-4 flex justify-between items-center">
        <div className="flex items-center">
          <img
            src={logo}
            alt="Logo"
            className="w-16 h-16 ml-4 transform transition-transform duration-300 ease-in-out hover:scale-150"
            style={{ transition: 'transform 0.6s ease-in-out' }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'scale(1.5) rotate(360deg)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'scale(1) rotate(0deg)';
            }}
          />
        </div>
        <div className="hidden md:flex space-x-6">
          <Link to="/" className={`text-white hover:text-gray-400 transition duration-300 flex items-center ${location.pathname === '/' ? 'bg-indigo-500' : ''}`}>
            <FaHome className="mr-2" /> {t('navbar.home')}
          </Link>
          <Link to="/about" className={`text-white hover:text-gray-400 transition duration-300 flex items-center ${location.pathname === '/about' ? 'bg-indigo-500' : ''}`}>
            <FaUser className="mr-2" /> {t('navbar.about')}
          </Link>
          <Link to="/experience" className={`text-white hover:text-gray-400 transition duration-300 flex items-center ${location.pathname === '/experience' ? 'bg-indigo-500' : ''}`}>
            <FaTools className="mr-2" /> {t('navbar.experience')}
          </Link>
          <Link to="/projects" className={`text-white hover:text-gray-400 transition duration-300 flex items-center ${location.pathname === '/projects' ? 'bg-indigo-500' : ''}`}>
            <FaProjectDiagram className="mr-2" /> {t('navbar.projects')}
          </Link>
          <Link to="/testimonials" className={`text-white hover:text-gray-400 transition duration-300 flex items-center ${location.pathname === '/testimonials' ? 'bg-indigo-500' : ''}`}>
            <FaStar className="mr-2" /> {t('navbar.testimonials')}
          </Link>
          <Link to="/blog" className={`text-white hover:text-gray-400 transition duration-300 flex items-center ${location.pathname === '/blog' ? 'bg-indigo-500' : ''}`}>
            <FaBlog className="mr-2" /> {t('navbar.blog')}
          </Link>
          <Link to="/games" className={`text-white hover:text-gray-400 transition duration-300 flex items-center ${location.pathname === '/games' ? 'bg-indigo-500' : ''}`}>
            <FaGamepad className="mr-2" /> {t('navbar.games')}
          </Link>
          <Link to="/contact" className={`text-white hover:text-gray-400 transition duration-300 flex items-center ${location.pathname === '/contact' ? 'bg-indigo-500' : ''}`}>
            <FaEnvelope className="mr-2" /> {t('navbar.contact')}
          </Link>
          <div className="flex items-center space-x-2">
            <FaGlobe className="text-white" />
            <select
              onChange={(e) => changeLanguage(e.target.value)}
              className="bg-transparent text-white border-none outline-none"
              defaultValue="fr"
            >
              <option value="en" className="text-black">EN</option>
              <option value="fr" className="text-black">FR</option>
              <option value="ar" className="text-black">AR</option>
            </select>
          </div>
        </div>
        <div className="md:hidden flex items-center">
          <button className="outline-none mobile-menu-button" onClick={toggleMenu}>
            {menuOpen ? (
              <svg
                className="w-6 h-6 text-white"
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path d="M6 18L18 6M6 6l12 12" />
              </svg>
            ) : (
              <svg
                className="w-6 h-6 text-white"
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path d="M4 6h16M4 12h16m-7 6h7" />
              </svg>
            )}
          </button>
        </div>
      </div>
      <div className={`mobile-menu ${menuOpen ? 'block' : 'hidden'} md:hidden transition duration-300 ease-in-out`}>
        <ul>
          <li className={`${location.pathname === '/' ? 'bg-indigo-500' : ''}`}>
            <Link to="/" className="block text-sm px-2 py-4 text-white font-semibold flex items-center"><FaHome className="mr-2" /> {t('navbar.home')}</Link>
          </li>
          <li className={`${location.pathname === '/about' ? 'bg-indigo-500' : ''}`}>
            <Link to="/about" className="block text-sm px-2 py-4 text-white hover:bg-indigo-500 transition duration-300 flex items-center"><FaUser className="mr-2" /> {t('navbar.about')}</Link>
          </li>
          <li className={`${location.pathname === '/experience' ? 'bg-indigo-500' : ''}`}>
            <Link to="/experience" className="block text-sm px-2 py-4 text-white hover:bg-indigo-500 transition duration-300 flex items-center"><FaTools className="mr-2" /> {t('navbar.experience')}</Link>
          </li>
          <li className={`${location.pathname === '/projects' ? 'bg-indigo-500' : ''}`}>
            <Link to="/projects" className="block text-sm px-2 py-4 text-white hover:bg-indigo-500 transition duration-300 flex items-center"><FaProjectDiagram className="mr-2" /> {t('navbar.projects')}</Link>
          </li>
          <li className={`${location.pathname === '/testimonials' ? 'bg-indigo-500' : ''}`}>
            <Link to="/testimonials" className="block text-sm px-2 py-4 text-white hover:bg-indigo-500 transition duration-300 flex items-center"><FaStar className="mr-2" /> {t('navbar.testimonials')}</Link>
          </li>
          <li className={`${location.pathname === '/blog' ? 'bg-indigo-500' : ''}`}>
            <Link to="/blog" className="block text-sm px-2 py-4 text-white hover:bg-indigo-500 transition duration-300 flex items-center"><FaBlog className="mr-2" /> {t('navbar.blog')}</Link>
          </li>
          <li className={`${location.pathname === '/games' ? 'bg-indigo-500' : ''}`}>
            <Link to="/games" className="block text-sm px-2 py-4 text-white hover:bg-indigo-500 transition duration-300 flex items-center"><FaGamepad className="mr-2" /> {t('navbar.games')}</Link>
          </li>
          <li className={`${location.pathname === '/contact' ? 'bg-indigo-500' : ''}`}>
            <Link to="/contact" className="block text-sm px-2 py-4 text-white hover:bg-indigo-500 transition duration-300 flex items-center"><FaEnvelope className="mr-2" /> {t('navbar.contact')}</Link>
          </li>
          <li className="flex items-center px-2 py-4">
            <FaGlobe className="text-white mr-2" />
            <select
              onChange={(e) => changeLanguage(e.target.value)}
              className="bg-transparent text-white border-none outline-none"
              defaultValue="fr"
            >
              <option value="en" className="text-black">EN</option>
              <option value="fr" className="text-black">FR</option>
              <option value="ar" className="text-black">AR</option>
            </select>
          </li>
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;
