import React, { useState } from 'react';
import SnakeGame from '../components/SnakeGame';
import SpeedTypingGame from '../components/SpeedTypingGame'; // Importez le nouveau jeu

const GamesPage = () => {
  const [selectedGame, setSelectedGame] = useState('snake');

  const renderGame = () => {
    switch (selectedGame) {
      case 'snake':
        return <SnakeGame />;
      case 'typing':
        return <SpeedTypingGame />;
      default:
        return <div>Selectionnez un jeu</div>;
    }
  };

  return (
    <div className="w-full min-h-screen flex flex-col items-center bg-gradient-to-br from-purple-500 via-pink-200 to-yellow-400 py-32 px-8">
      <div className="max-w-screen-lg w-full mx-auto px-8 py-8 bg-white bg-opacity-90 rounded-lg shadow-2xl backdrop-blur-md">
        <h2 className="text-5xl font-extrabold mb-12 text-center text-gray-800">
          Jeux
        </h2>
        <div className="mb-8 flex justify-center">
          <button onClick={() => setSelectedGame('snake')} className="px-4 py-2 mx-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300">
            Snake
          </button>
          <button onClick={() => setSelectedGame('typing')} className="px-4 py-2 mx-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300">
            Speed Typing
          </button>
        </div>
        <div className="w-full flex justify-center">
          {renderGame()}
        </div>
      </div>
    </div>
  );
};

export default GamesPage;
