import React, { useState } from 'react';

const articles = [
  { 
    id: 1, 
    title: 'L’Intelligence Artificielle en 2024 : Nouvelles Avancées', 
    description: 'Découvrez les dernières avancées en IA cette année.', 
    content: 'En 2024, l’intelligence artificielle a fait des progrès significatifs dans le domaine de la médecine, de l’automatisation industrielle et de la gestion de données. Les nouvelles technologies d’apprentissage automatique permettent des diagnostics plus précis et une meilleure optimisation des processus.', 
    link: 'https://www.ibm.com/blog/most-important-ai-trends-2024' 
  },
  { 
    id: 2, 
    title: 'Les Dernières Tendances du Cloud Computing en 2024', 
    description: 'Exploration des innovations récentes dans le cloud computing.', 
    content: 'Les tendances actuelles du cloud computing en 2024 incluent l’adoption croissante du multi-cloud, les avancées en matière de sécurité cloud, et l’utilisation accrue de l’IA pour la gestion et l’optimisation des ressources cloud.', 
    link: 'https://www.cloudcomputing-news.net/news/2024/jan/31/cloud-computing-trends-2024/' 
  },
  { 
    id: 3, 
    title: 'Technologies de la Santé : Innovations Récentes', 
    description: 'Un regard sur les technologies de santé révolutionnaires de 2024.', 
    content: 'Les technologies de la santé continuent de transformer les soins médicaux. Les innovations telles que les implants biométriques, la télémédecine avancée et les thérapies géniques personnalisées améliorent la qualité de vie des patients.', 
    link: 'https://www.healthcareitnews.com/news/technology-innovations-healthcare-2024' 
  },
  { 
    id: 4, 
    title: 'Cybersécurité en 2024 : Nouvelles Menaces et Solutions', 
    description: 'Analyse des nouvelles menaces et des solutions de cybersécurité en 2024.', 
    content: 'Les menaces de cybersécurité évoluent rapidement en 2024 avec des attaques de plus en plus sophistiquées. Les solutions incluent l’utilisation de l’IA pour détecter et répondre aux menaces en temps réel, ainsi que des approches de sécurité Zero Trust.', 
    link: 'https://www.csoonline.com/article/3611128/top-cybersecurity-trends-2024.html' 
  },
  { 
    id: 5, 
    title: 'L’Internet des Objets (IoT) : Tendances Actuelles et Futur', 
    description: 'Un aperçu des tendances actuelles et des développements futurs de l’IoT.', 
    content: 'En 2024, l’Internet des Objets continue de croître avec l’augmentation des dispositifs connectés et des plateformes IoT. Les innovations incluent des améliorations en matière de sécurité IoT et l’intégration avec les technologies de smart city.', 
    link: 'https://www.iotworldtoday.com/latest-trends-iot-2024' 
  },
  { 
    id: 6, 
    title: 'La Réalité Augmentée et Virtuelle : Nouvelles Applications', 
    description: 'Exploration des nouvelles applications de la RA et RV en 2024.', 
    content: 'La réalité augmentée et virtuelle trouvent de nouvelles applications en 2024 dans les domaines de l’éducation, de la formation professionnelle, et du divertissement. Les avancées technologiques rendent ces expériences plus immersives et accessibles.', 
    link: 'https://www.vrfocus.com/news/2024/01/ar-vr-trends-2024/' 
  },
];

const Blog = () => {
  const [currentPage, setCurrentPage] = useState(1);
  const [searchTerm, setSearchTerm] = useState('');
  const itemsPerPage = 3;

  const filteredArticles = articles.filter(article =>
    article.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    article.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
    article.content.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalPages = Math.ceil(filteredArticles.length / itemsPerPage);
  const displayedArticles = filteredArticles.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const handleSearch = event => {
    setSearchTerm(event.target.value);
    setCurrentPage(1);
  };

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  return (
    <div className="w-full min-h-screen flex flex-col items-center bg-gradient-to-br from-blue-900 to-gray-700 py-32 px-8">
      <div className="max-w-screen-lg w-full mx-auto px-8 py-8 bg-gray-900 bg-opacity-70 rounded-lg shadow-2xl backdrop-blur-md">
        <h2 className="text-5xl font-extrabold mb-12 text-center text-white">
          Blog
        </h2>
        <div className="mb-8">
          <input
            type="text"
            placeholder="Rechercher..."
            value={searchTerm}
            onChange={handleSearch}
            className="w-full p-4 rounded-lg bg-gray-800 text-white placeholder-gray-400"
          />
        </div>
        <div className="grid gap-8 sm:grid-cols-1 md:grid-cols-2 lg:grid-cols-2">
          {displayedArticles.map(({ id, title, description, content, link }) => (
            <ArticleCard key={id} title={title} description={description} content={content} link={link} />
          ))}
        </div>
        <Pagination
          totalPages={totalPages}
          currentPage={currentPage}
          onPageChange={handlePageChange}
        />
      </div>
    </div>
  );
};

const ArticleCard = ({ title, description, content, link }) => {
  return (
    <div className="bg-gray-800 bg-opacity-80 p-6 rounded-lg shadow-lg transform hover:-translate-y-2 hover:bg-opacity-90 transition duration-300 ease-in-out">
      <h3 className="text-2xl font-bold mb-2 text-white">{title}</h3>
      <p className="text-lg mb-4 text-gray-300 leading-relaxed">{description}</p>
      <p className="text-sm mb-4 text-gray-400">{content}</p>
      <a href={link} className="text-yellow-300 hover:underline">
        Lire la suite
      </a>
    </div>
  );
};

const Pagination = ({ totalPages, currentPage, onPageChange }) => {
  const pages = [];

  for (let i = 1; i <= totalPages; i++) {
    pages.push(
      <button
        key={i}
        onClick={() => onPageChange(i)}
        className={`px-4 py-2 rounded-lg ${currentPage === i ? 'bg-yellow-500 text-white' : 'bg-gray-800 text-gray-400'} mx-1`}
      >
        {i}
      </button>
    );
  }

  return (
    <div className="mt-8 flex justify-center">
      {pages}
    </div>
  );
};

export default Blog;
